 dict(when="2026-10-23 14:17",who="Humberto Salazar (@drhsalazar)",where="X, Spanish, about 2.8 million views",url="https://x.com/drhsalazar/status/2113590567510647121",
  text="Says El Salvador announced sending a contingent of 3,000 troops, says the four are probably dead, and names Claude Celestin (Chen Mechan) and Wilson Joseph, Lanmò San Jou (400 Mawozo), as the leaders of the groups that hold the area. Asks whether Haiti will be \"Bukele's Waterloo.\" Bukele quoted this post in his reply at 20:59.",
  evidence="2 photos; says \"according to the international press\"; no named source",other="We did not find a 3,000 figure in any Bukele post we read.",links=[]),
