 dict(when='2026-10-22 00:27',who='Jake Johnston (@JakobJohnston), Haiti analyst at CEPR, author of "Aid State"',where="X, English, about 17,000 followers",url='https://x.com/JakobJohnston/status/2113019282225541547',
  text="Says Bukele stated the Salvadoran military is directly taking part in an ongoing security operation in Haiti, after the four Salvadoran troops with the Gang Suppression Force were reportedly ambushed on Sunday; quotes Bukele's ultimatum to the armed groups (\"Return our four compatriots to us alive, without any harm\"); says the Gang Suppression Force thanked El Salvador for its \"additional support\" the night before, and that \"Haitian authorities are silent.\"",
  evidence="two photos; quotes Bukele and the Gang Suppression Force; his own note on Haitian silence",other="",links=[]),
 dict(when="2026-10-21 21:58",who="Nayib Bukele (@nayibbukele)",where="X, in Haitian Creole",url="https://x.com/nayibbukele/status/2112981920741310695",
  text="Addresses the gang chiefs and members holding the four: they are aviation technicians, not combatants; they were seized \"cowardly\" while returning from buying food at a market; \"today we launched a military operation to rescue them\"; \"today's attack is nothing compared to what is coming if you do not hand over all four hostages alive\"; \"we have already finished with the gangs in El Salvador, and we can finish with you too.\"",
  evidence="on the record, signed post; video, 60 seconds (not yet watched by us)",other="",links=[]),
 dict(when="2026-10-21",who="Kim Ives in Haïti Liberté",where="Haitian-American weekly",url="https://haitiliberte.com/the-u-s-denies-that-its-salvadoran-mercenaries-have-been-killed/",
  text="Reports an account he says Jimmy \"Barbecue\" Chérizier, spokesman of Viv Ansanm, gave him: five GSF members were ambushed at a supermarket in Santo on 18 Oct by Chen Mechan fighters, their armored Land Cruiser was set on fire, all five died, and the gang is holding the bodies. The article's own title uses the word \"mercenaries\" for them. Says the New York Times reported five Salvadoran soldiers missing citing \"three people familiar with the situation,\" while the Salvadoran military says four. Says the GSF is at 28 percent of capacity.",
  evidence="one named gang leader's account as relayed by the author; not yet reported by others; no photo or video given",other="Salvadoran military and AP: four aviation technicians fled the burning vehicle and are unaccounted for. Ambassador Waltz told the UN Security Council on 19 Oct that attackers fired hundreds of rounds and used explosives and that authorities believe all four survived.",links=[]),
 dict(when='2026-10-19 19:40',who='Jake Johnston (@JakobJohnston), Haiti analyst at CEPR, author of "Aid State"',where="X, English, about 17,000 followers",url='https://x.com/JakobJohnston/status/2112222350884180099',
  text="Says you cannot separate the success of Haiti's elites from the collapse of the country on display today, as he told the New York Times: \"They are two sides of the same coin.\"",
  evidence="two images; on the record, signed post",other="",links=[]),
 dict(when='2026-10-19 18:41',who='Jake Johnston (@JakobJohnston), Haiti analyst at CEPR, author of "Aid State"',where="X, English, about 17,000 followers",url='https://x.com/JakobJohnston/status/2112207579854045593',
  text="Says helicopter-backed security operations continued that day in Haiti after four Salvadoran soldiers deployed with the Gang Suppression Force were ambushed the day before and remain missing; credits reporting by Jacqueline Charles in a follow-up.",
  evidence="two images; credits Miami Herald reporter Jacqueline Charles",other="",links=[]),
 dict(when="2026-10-19",who="Mike Waltz, US ambassador to the UN, speaking at the Security Council; reported by EFE via France 24",where="UN Security Council",url="https://www.france24.com/es/minuto-a-minuto/20261024-el-salvador-despliega-tropas-en-hait%C3%AD-para-buscar-a-cuatro-soldados-desaparecidos",
  text="Said the four Salvadorans disappeared on Sunday 18 Oct when armed gangs attacked their armored vehicle as they returned to base from a market on the outskirts of Port-au-Prince, that attackers fired hundreds of rounds and used explosives, and that authorities believe all four survived. On X the US mission to the UN told gang bosses: \"The Gang Suppression Force is coming for you.\"",
  evidence="on the record, named official",other="",links=[("US mission to the UN on X, 19 Oct","https://x.com/USAmbUN/status/2112201424788693158")]),
 dict(when="2026-10-19",who="United Nations, press release SC/16482",where="UN Security Council briefing",url="https://press.un.org/en/2026/sc16482.doc.htm",
  text="UN officials told the Security Council that between July and September over 1,000 people were killed and over 100 abducted in Haiti, and described the Gang Suppression Force as severely understrength.",
  evidence="on the record, UN document",other="",links=[]),
